// SAFETY: refuses every request, which `Alloc` allows; nothing is ever live.
unsafe impl Alloc for Refuse {
    fn malloc(_: usize, _: Option<&core::ffi::CStr>, _: i32) -> Option<core::ptr::NonNull<u8>> {
