input.command:
python3 - <<'EOF'
import json,re,subprocess,collections
s=json.load(open('crustify/artifacts/schedule.json'))
items=[]
def walk(x):
    if isinstance(x,dict):
        if 'items' in x and isinstance(x['items'],list):
            for it in x['items']:
                if isinstance(it,dict) and 'kind' in it and 'name' in it: items.append(it)
        for v in x.values(): walk(v)
    elif isinstance(x,list):
        for v in x: walk(v)
walk(s)
kinds=collections.Counter(i['kind'] for i in items)
print(len(items),kinds)
tk={'struct':'st','union':'un','enum':'enm','typedef':'tdf'}
types={(tk[i['kind']],i['name']) for i in items if i['kind'] in tk}
print('types',len(types), ('st','dv_info_t') in types)
for t in ['crustify/tmp/base','.']:
    out=subprocess.run(['grep','-rhoE',r'(Wraps|Replaces) `(st|un|enm|tdf)::[A-Za-z0-9_]+`',t+'/src'],capture_output=True,text=True).stdout.split('\n')
    w=set();r=set()
    for l in out:
        m=re.match(r'(Wraps|Replaces) `(\w+)::(\w+)`',l)
        if m: (w if m[1]=='Wraps' else r).add((m[2],m[3]))
    print(t,'wrapped',len(types&(w-r)),len(types&w),'ported',len(types&r))
EOF

